The timer is never removed from `timers`. In a long-running server, every completed request leaves an entry behind, causing unbounded memory growth.

Remove the entry when the request finishes, preferably in a `finally` block:

```js
const timers = new Map();

function startTimer(requestId) {
  timers.set(requestId, performance.now());
}

function elapsed(requestId) {
  const start = timers.get(requestId);
  if (start === undefined) return null;

  const duration = performance.now() - start;
  timers.delete(requestId);
  return duration;
