  if (n === 0) return [y, m, d];

  const cycleDays = 146097;
  const cycles = Math.floor(n / cycleDays);
  y += cycles * 400;
  n %= cycleDays;

  const isLeapYear = year =>
    year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);

  while (n > 0) {
    const daysInMonth = [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];

    if (d + n <= daysInMonth) {
      d += n;
      n = 0;
    } else {
      n -= daysInMonth - d + 1;
