    if (month === 2) {
      return (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) ? 29 : 28;
    }
    return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  };

  while (n > 0) {
    const dim = daysInMonth(y, m);
    if (d + n <= dim) {
      d += n;
      n = 0;
    } else {
      n -= (dim - d + 1);
      d = 1;
      m++;
      if (m > 12) {
        m = 1;
        y++;
      }
    }
  }

  return [y, m, d];
