    year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);

  const daysInYear = year => isLeapYear(year) ? 366 : 365;

  const daysInMonth = (year, month) => {
    if (month === 2) return isLeapYear(year) ? 29 : 28;
    return [4, 6, 9, 11].includes(month) ? 30 : 31;
  };

  while (n > 0) {
    if (m === 1 && d === 1 && n >= 146097) {
      const cycles = Math.floor(n / 146097);
      y += cycles * 400;
      n -= cycles * 146097;
      continue;
    }

    const remainingInMonth = daysInMonth(y, m) - d + 1;

    if (n < remainingInMonth) {
      d += n;
      n = 0;
    } else {
      n -= remainingInMonth;
      d = 1;
      m++;

      if (m > 12) {
        m = 1;
        y++;
      }
    }
  }

  return [y, m, d];
}

function minRooms(meetings) {
  const starts = [];
  const ends = [];

  for (const [start, end] of meetings) {
    if (start < end) {
      starts.push(start);
      ends.push(end);
    }
  }

  starts.sort((a, b) => a - b);
  ends.sort((a, b) => a - b);

  let startIndex = 0;
  let endIndex = 0;
  let active = 0;
  let rooms = 0;

  while (startIndex < starts.length) {
    if (endIndex < ends.length && starts[startIndex] >= ends[endIndex]) {
      active--;
      endIndex++;
    } else {
      active++;
      rooms = Math.max(rooms, active);
      startIndex++;
    }
  }

  return rooms;
}

**Defect:** `deleteUser` does not invalidate the cache.

**Impact:** After a user is deleted, `getUser(id)` will return a stale cached object instead of `undefined` or throwing a "not found" error. This causes the application to operate on phantom data, potentially leading to incorrect UI state, logic errors, or attempts to use deleted user records.

**Fix:** Add `cache.delete(id);` to `deleteUser` (ideally before or after the DB call, but consistently with the other functions):

```javascript
async function deleteUser(id) {
  await db.deleteUser(id);
  cache.delete(id); // <-- add this
}
```

`deleteUser` does not invalidate the cache. After a successful deletion, `getUser(id)` can return the deleted user from `cache`.

```js
async function deleteUser(id) {
  await db.deleteUser(id);
  cache.delete(id);
}
```

`renameUser` already performs the required invalidation.

**Correctness defect:** The `timers` Map is never cleaned up. `startTimer` adds entries but nothing removes them after the request completes.

**Concrete impact:** In a long-running server, the Map grows unboundedly, causing a memory leak. Additionally, `elapsed()` can return stale durations if called after a request has finished, and repeated lookups for completed requests waste CPU.

**Fix:** Remove the entry when the request lifecycle ends. For example, export a cleanup helper and call it in your request handler's finally block, or return a disposable object:

```js
function startTimer(requestId) {
  timers.set(requestId, Date.now());
  return () => timers.delete(requestId); // call when request finishes
}
```

If `requestId` can be reused across requests, also guard against overwriting a still-active timer.

**Defect:** The `except Exception: pass` clause silently swallows all non-`TimeoutError` failures (e.g., `ConnectionError`, `HTTPError`, `ValueError`). 

**Impact:** If a non-timeout error occurs, the loop continues without recording it. If all attempts fail with non-timeout errors, `last_error` remains `None` and the function raises `None`, which crashes with a cryptic `TypeError: exceptions must be derived from BaseException` instead of surfacing the actual failure. Even if a timeout occurs later, the original non-timeout error is permanently lost.

**Fix:** Capture and re-raise non-timeout exceptions immediately, or store them consistently:
```python
def fetch_with_retry(url, attempts=3):
    last_error = None
    for _ in range(attempts):
        try:
            return http_get(url)
        except Exception as e:
            last_error = e
            if not isinstance(e, TimeoutError):
                raise  # fail fast on non-timeout errors
    raise last_error
```
*(Adjust the `raise` vs `continue` behavior based on whether you want to retry on all errors or only timeouts.)*

**Defect:** The loop termination condition assumes the API returns fewer items than `pageSize` only when the final page is reached. If the endpoint returns an empty array (`[]`) for a valid page (e.g., due to filtering, transient errors, or a server that omits a `total` count), `batch.length < pageSize` evaluates to `true` and the loop breaks prematurely, silently dropping remaining data.

**Concrete impact:** Incomplete result sets. For example, if the server returns `[]` on page 2 but has data on page 3, the function stops at page 2 and returns a truncated array, leading to missing records in the caller.

**Fix:** Add an explicit empty-response guard so the loop only breaks when there is genuinely no more data, while still allowing the `< pageSize` check to catch the true final page:

```javascript
async function fetchAll(endpoint, pageSize) {
  const out = [];
  let page = 0;
  while (true) {
    const batch = await get(`${endpoint}?offset=${page * pageSize}&limit=${pageSize}`);
    if (batch.length === 0) break;          // explicit end-of-data guard
    out.push(...batch);
    if (batch.length < pageSize) break;     // true final page
    page++;
  }
  return out;
}
```

*(Note: If the API supports a `total` count header or a cursor-based pagination scheme, prefer those over offset/limit to avoid similar edge cases and performance degradation on large datasets.)*

The code has a resource-lifetime defect: entries are never removed from `timers`. Every completed request leaves its ID and timestamp in the global `Map`, causing unbounded memory growth (and stale timings if an ID is accidentally reused).

Delete the entry when the request completes, ideally in a `finally` block:

```js
const timers = new Map();

function startTimer(requestId) {
  timers.set(requestId, Date.now());
}

function elapsed(requestId) {
  const start = timers.get(requestId);
  if (start === undefined) return null;

  const result = Date.now() - start;
  timers.delete(requestId);
  return result;
}
```

For robust elapsed durations, use a monotonic clock such as `performance.now()` (or `process.hrtime.bigint()` in Node), since `Date.now()` can jump due to system-clock adjustments.

The pagination logic is correct for a positive, finite `pageSize`, but it lacks input validation. With `pageSize === 0` (or a negative/invalid value), `batch.length < pageSize` may never be true, causing an infinite loop and repeated requests.

Validate the argument before looping:

```js
async function fetchAll(endpoint, pageSize) {
  if (!Number.isInteger(pageSize) || pageSize <= 0) {
    throw new TypeError("pageSize must be a positive integer");
  }

  const out = [];
  let page = 0;

  while (true) {
    const batch = await get(
      `${endpoint}?offset=${page * pageSize}&limit=${pageSize}`
    );
    out.push(...batch);

    if (batch.length < pageSize) break;
    page++;
  }

  return out;
}
```

The helper has correctness defects:

- `except Exception: pass` silently discards non-`TimeoutError` failures. If every call raises, for example, `ConnectionError`, `last_error` remains `None`, and `raise last_error` produces a misleading `TypeError` instead of the original error.
- A later non-timeout error is also masked by an earlier timeout.
- `attempts <= 0` performs no calls and likewise attempts to `raise None`.

If only timeouts are retryable, let other exceptions propagate and validate `attempts`:

```python
def fetch_with_retry(url, attempts=3):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    for attempt in range(attempts):
        try:
            return http_get(url)
        except TimeoutError:
            if attempt == attempts - 1:
                raise
```

If other exceptions are retryable, catch an explicit tuple of expected transient exception types and preserve or re-raise the final exception rather than swallowing it.

The code is **correct** for comparing two version arrays of non-negative numbers (e.g., `[1, 2, 3]` vs `[1, 2, 4]`). It properly handles arrays of unequal length by treating missing segments as `0`, and returns `-1`, `1`, or `0` as expected.

**Potential defect (edge case):** If the arrays contain non-numeric values (e.g., strings like `"1.0"` or `undefined` passed directly), the `<` comparison may produce incorrect results or `NaN` behavior. Also, if negative numbers are allowed, the logic still works but may not match semantic versioning conventions.

**Fix (if robustness is needed):**
```javascript
function compareVersions(a, b) {
  const len = Math.max(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const x = Number(a[i]) || 0;
    const y = Number(b[i]) || 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}
```
This ensures non-numeric entries are coerced to `0`, making the function more defensive. For standard numeric version arrays, the original code is fine.

The comparison is correct **if** both arrays contain valid numeric version components (e.g., non-`NaN` numbers). Missing components are correctly treated as `0`.

A defect occurs for invalid or nonnumeric values. For example:

```js
compareVersions([NaN], [1]) // 1
compareVersions([1], [NaN]) // 1
```

Because `NaN < value` is always false, the function reports both directions as greater, violating comparison symmetry. Strings or other mixed types can similarly produce inconsistent results due to strict equality followed by coercive `<`.

Fix by validating and normalizing inputs before comparing:

```js
function compareVersions(a, b) {
  const len = Math.max(a.length, b.length);

  for (let i = 0; i < len; i++) {
    const x = i < a.length ? a[i] : 0;
    const y = i < b.length ? b[i] : 0;

    if (!Number.isFinite(x) || !Number.isFinite(y)) {
      throw new TypeError("Version components must be finite numbers");
    }
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}
```

With the usual assumption of finite numeric components, the original code is correct.

